const input = $input.first().json || {};

const allowed = new Set([
  'read_contact_by_id',
  'create_contact',
  'update_contact_by_id',
  'search_contact_by_email',
  'batch_read_contact_by_email'
]);

const operation = String(input.operation || '').trim();

if (!allowed.has(operation)) {
  throw new Error(`HubSpot broker rejected operation: ${operation}`);
}

const base = 'https://api.hubapi.com';
const version = '2026-09';

const defaultProperties = [
  'email',
  'firstname',
  'lastname',
  'company',
  'jobtitle',
  'saray_gtm_contact_key',
  'saray_gtm_account_id',
  'saray_gtm_persona',
  'saray_linkedin_url'
];

let method = null;
let url = null;
let body = null;

if (operation === 'read_contact_by_id') {
  const id = String(input.contact_id || '').trim();

  if (!id) {
    throw new Error('HubSpot broker requires contact_id for read_contact_by_id');
  }

  method = 'GET';

  // Put properties directly into the URL. This avoids n8n dynamic-query
  // toggling dropping the properties parameter on GET.
  const propCsv = defaultProperties.join(',');
  url =
    `${base}/crm/objects/${version}/contacts/${encodeURIComponent(id)}` +
    `?properties=${encodeURIComponent(propCsv)}`;
}

if (operation === 'create_contact') {
  const payload = input.payload;

  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('HubSpot broker requires object payload for create_contact');
  }

  method = 'POST';
  url = `${base}/crm/objects/${version}/contacts`;
  body = payload;
}

if (operation === 'update_contact_by_id') {
  const id = String(input.contact_id || '').trim();
  const payload = input.payload;

  if (!id) {
    throw new Error('HubSpot broker requires contact_id for update_contact_by_id');
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    throw new Error('HubSpot broker requires object payload for update_contact_by_id');
  }

  method = 'PATCH';
  url = `${base}/crm/objects/${version}/contacts/${encodeURIComponent(id)}`;
  body = payload;
}

if (operation === 'search_contact_by_email') {
  const email = String(input.contact_email || '').trim().toLowerCase();

  if (!email || !email.includes('@')) {
    throw new Error('HubSpot broker requires contact_email for search_contact_by_email');
  }

  method = 'POST';
  url = `${base}/crm/objects/${version}/contacts/search`;
  body = {
    filterGroups: [
      {
        filters: [
          {
            propertyName: 'email',
            operator: 'EQ',
            value: email
          }
        ]
      }
    ],
    properties: defaultProperties,
    limit: 2
  };
}

if (operation === 'batch_read_contact_by_email') {
  const email = String(input.contact_email || '').trim().toLowerCase();

  if (!email || !email.includes('@')) {
    throw new Error('HubSpot broker requires contact_email for batch_read_contact_by_email');
  }

  method = 'POST';
  url = `${base}/crm/objects/${version}/contacts/batch/read`;
  body = {
    inputs: [{ id: email }],
    properties: defaultProperties,
    propertiesWithHistory: [],
    idProperty: 'email'
  };
}

return [{
  json: {
    broker_version: 'HS-BROKER-V2.0.0',
    operation,
    method,
    url,
    body
  }
}];

const req = $('Validate and Route HubSpot Operation').first().json;
const response = $input.first().json;

return [{
  json: {
    broker: 'hubspot',
    broker_version: req.broker_version,
    operation: req.operation,
    response
  }
}];
